from produire import produire,paras,table,steps
from medicaments import aciclovir
parts=[
('La gingivostomatite herpétique est une infection buccale liée au virus herpès simplex. Le {tableau de primo-infection} associe souvent gingivite diffuse, vésicules puis ulcérations.',paras('Elle ne se confond ni avec un bouton de fièvre isolé ni avec une aphtose herpétiforme. La douleur peut empêcher de boire et devenir le principal problème immédiat.')),
('Elle survient fréquemment chez l’enfant mais peut atteindre l’adulte. Le {contexte de transmission} comprend un contact avec des sécrétions infectées.',paras('Une personne porteuse peut transmettre le virus même sans lésion reconnue. Le terrain immunitaire influence gravité et durée ; une forme atypique chez l’adulte ne doit pas être écartée sur le seul âge.')),
('La réplication virale endommage l’épithélium et provoque des lésions douloureuses. Les {bases virologiques} expliquent la possibilité de récidives ultérieures.',paras('Après l’infection, le virus persiste à l’état latent dans les ganglions sensitifs. Les antiviraux limitent la réplication mais n’éradiquent pas cette latence. Une gingivite diffuse distingue souvent la primo-infection d’une récidive labiale limitée.')),
('Évaluer immédiatement la capacité à boire et le terrain. Les {signes de gravité} nécessitent une prise en charge urgente.',paras('Déshydratation, trouble neurologique, atteinte oculaire, nouveau-né, immunodépression importante ou lésions très étendues imposent une évaluation spécialisée. Douleur oculaire, photophobie ou baisse visuelle requièrent un avis ophtalmologique le jour même ; ne pas appliquer de corticoïde oculaire empirique.')),
('L’entretien précise fièvre, début des lésions et prise de liquides. Les {questions utiles} recherchent extension et exposition à risque.',paras('Noter diminution des urines, vomissements, douleur oculaire, symptômes neurologiques, eczéma étendu et médicaments immunosuppresseurs. Demander les contacts avec nourrissons ou personnes vulnérables pour adapter les conseils de prévention.')),
('L’examen recherche gingivite inflammatoire et lésions vésiculo-ulcéreuses multiples. Les {éléments de distribution} aident au diagnostic différentiel.',paras('Les lésions peuvent toucher gencives, langue, lèvres et palais ; les vésicules fragiles ne sont pas toujours visibles au moment de l’examen. Inspecter peau, mains et pieds, et évaluer hydratation et état général.')),
('Une ulcération multiple n’est pas toujours herpétique. Le {diagnostic différentiel} repose notamment sur gingivite, topographie et signes associés.',table(['Présentation','Alternative'],[['Aphtes récidivants sans gingivite diffuse.','Aphtose, y compris forme herpétiforme.'],['Lésions buccales et éruption des mains ou pieds.','Syndrome pieds-mains-bouche.'],['Lésions postérieures et fièvre.','Herpangine selon le contexte.'],['Lésions étendues avec peau, yeux ou nouveau médicament.','Maladie bulleuse ou réaction cutanéo-muqueuse sévère à évaluer en urgence.']])) ,
('Le diagnostic est souvent clinique devant un tableau typique. Les {conditions de certitude} deviennent plus importantes si la maladie est atypique ou grave.',paras('Fièvre, gingivite diffuse et ulcérations multiples soutiennent le diagnostic. Une sérologie ancienne positive n’attribue pas automatiquement une lésion actuelle au virus.')),
('Un prélèvement virologique n’est pas systématique dans une forme simple. Les {examens ciblés} répondent à un doute ou à un risque élevé.',paras('Une PCR sur lésion peut être discutée si présentation atypique, immunodépression ou résultat susceptible de modifier la prise en charge. Une complication neurologique, oculaire ou disséminée relève de son bilan urgent spécifique ; ne pas attendre une confirmation locale pour l’orienter.')),
('L’{arbre de prise en charge} commence par hydratation et gravité. L’antiviral se discute selon sévérité, durée et terrain.',steps('Évaluer boissons, urines, état général, œil et neurologie.', 'Adresser les formes graves ou à risque ; organiser réhydratation si nécessaire.', 'Pour une forme simple, soulager la douleur et proposer liquides et alimentation tolérés.', 'Discuter un antiviral systémique dans les formes sévères, persistantes ou à risque, de préférence précocement ; revoir rapidement si aggravation.')),
('Les soins symptomatiques sont essentiels dans toutes les formes. Les {modalités de l’antiviral} exigent une préparation et une posologie adaptées.',paras('Les recommandations britanniques consultées ne rendent pas l’antiviral systématique dans les infections orales simples ; elles le proposent notamment dans les formes sévères, fréquentes ou persistantes. La notice suisse fournit le schéma de la préparation choisie.', '@@MEDICAMENTS@@')),
('Les {précautions de transmission} concernent les contacts directs et les mains. Il faut particulièrement protéger nouveau-nés et personnes immunodéprimées.',paras('Éviter baisers et partage d’objets en contact avec les lésions ou la salive pendant l’épisode. Se laver les mains, ne pas toucher les yeux après les lésions et éviter les contacts directs avec une peau eczémateuse.')),
('La gingivite diffuse aide à reconnaître une primo-infection herpétique. La déshydratation peut en faire une urgence. Une atteinte oculaire ou neurologique change immédiatement la filière. Un antiviral n’efface pas la latence virale.','')]
quiz=[('Un bouton de fièvre isolé équivaut-il à une gingivostomatite ?','Non : le tableau buccal diffus est différent.'),('Une gingivite diffuse aide-t-elle au diagnostic ?','Oui, avec fièvre et lésions multiples.'),('Les vésicules sont-elles toujours encore visibles ?','Non : elles peuvent être déjà rompues.'),('L’adulte peut-il être atteint ?','Oui.'),('Quel risque fonctionnel faut-il mesurer ?','L’incapacité à boire et la déshydratation.'),('Quels signes d’hydratation demander ?','Prises de liquides et urines, avec état général et examen.'),('Que faire devant une douleur oculaire ou une baisse visuelle ?','Avis ophtalmologique urgent le jour même.'),('Une aphtose herpétiforme est-elle une preuve de virus ?','Non.'),('Que suggèrent des lésions des paumes et plantes ?','Notamment un syndrome pieds-mains-bouche.'),('Une PCR est-elle systématique dans une forme typique simple ?','Non, elle est ciblée selon contexte.'),('Un antiviral est-il systématique pour chaque forme simple ?','Non : gravité, durée et terrain guident la décision.'),('Quel schéma adulte oral figure dans la notice citée pour une infection cutanéo-muqueuse simple ?','200 mg cinq fois par jour, toutes les quatre heures avec pause nocturne de huit heures, pendant cinq jours et plus ; fonction rénale normale.'),('Pourquoi contrôler la fonction rénale sous aciclovir ?','Son élimination est rénale et l’accumulation augmente notamment le risque neurologique.'),('Le traitement supprime-t-il définitivement le virus ?','Non : une latence persiste.')]
produire(4,parts,quiz,(7,13,16,20),aciclovir)
